import { getValidProjectToken } from '../auth/project-token.js';
import { awaitWithSignal } from './awaitWithSignal.js';
import { withRateLimitRetries } from './withRateLimitRetries.js';
const devJwtCache = new Map();
function devJwtCacheKey(baseUrl, contentSystemId) {
    return `${baseUrl}::${contentSystemId}`;
}
export function invalidateDevJwt(baseUrl, contentSystemId) {
    devJwtCache.delete(devJwtCacheKey(baseUrl, contentSystemId));
}
export async function getDevJwt({ baseUrl, contentSystemId, logger, signal }) {
    signal.throwIfAborted();
    const cacheKey = devJwtCacheKey(baseUrl, contentSystemId);
    const cached = devJwtCache.get(cacheKey);
    if (cached) {
        return cached;
    }
    const usesSuperUser = !contentSystemId || contentSystemId === 'test-system' || contentSystemId === '*';
    const fetchWithRetries = withRateLimitRetries({
        fetchImplementation: fetch,
        warn: (message)=>logger.warn(message)
    });
    const response = await fetchWithRetries(new URL('/dev/jwt', baseUrl), {
        body: JSON.stringify({
            content_system_id: usesSuperUser ? '*' : contentSystemId
        }),
        headers: {
            'Content-Type': 'application/json'
        },
        method: 'POST',
        signal
    });
    if (!response.ok) {
        throw new Error(`Failed to get dev JWT: ${response.status} ${response.statusText}`);
    }
    const { token } = await awaitWithSignal(response.json(), signal);
    signal.throwIfAborted();
    devJwtCache.set(cacheKey, token);
    logger.info?.(`Dev JWT acquired for content system: ${contentSystemId}`);
    return token;
}
export async function applyContentApiAuth(request, options) {
    const { auth, baseUrl, contentSystemId, logger } = options;
    request.signal.throwIfAborted();
    if (auth.mode === 'apiKey') {
        request.headers.set('X-Api-Key', auth.apiKey);
        return;
    }
    if (auth.mode === 'tokenStore') {
        const token = await awaitWithSignal(getValidProjectToken({
            ...auth.projectInfo ? {
                projectInfo: auth.projectInfo
            } : {},
            tenantId: contentSystemId,
            tokenStore: auth.tokenStore
        }), request.signal);
        request.signal.throwIfAborted();
        if (!token) {
            throw new Error('Authentication required. Run `npx @payloadcms/figma login` to authenticate.');
        }
        request.headers.set('Authorization', `Bearer ${token}`);
        return;
    }
    request.headers.set('Authorization', `Bearer ${await getDevJwt({
        baseUrl,
        contentSystemId,
        logger,
        signal: request.signal
    })}`);
}
